+        painlessLookup = PainlessLookupBuilder.buildFromWhitelists(Collections.singletonList(
+                WhitelistLoader.loadFromResourceFiles(PainlessPlugin.class, "org.elasticsearch.painless.lookup")
+        ));
+    }
+
